/*
 * prog37_binomial_coefficient.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program:
 *
 *   * expects exactly two command‑line arguments (n and k);
 *   * prints "NO_INPUT"   when fewer than two arguments are given;
 *   * prints "BAD_INPUT"  when either argument is not a pure decimal integer;
 *   * prints "OUT_OF_RANGE" when n is negative or larger than 60;
 *   * otherwise computes the binomial coefficient C(n,k) and prints it
 *     as a signed 64‑bit integer (format "%lld\n").
 *
 * The coefficient is computed recursively with memoisation, matching the
 * logic of the original `binom` function.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <errno.h>

#define MAX_N 60          /* limit imposed by the original binary */
#define OUT_OF_RANGE_MSG "OUT_OF_RANGE"
#define BAD_INPUT_MSG    "BAD_INPUT"
#define NO_INPUT_MSG     "NO_INPUT"

/* ----------------------------------------------------------------------
 * Memoised binomial coefficient.
 *
 * The original binary used two global tables:
 *   - `memo`   : stores the computed value for a given (n,k)
 *   - `computed` : a byte flag indicating that the entry is valid
 *
 * Because the program never calls `binom` with n > 60 (the range check
 * in `main` aborts earlier), we can safely allocate static tables of that
 * size.
 * ---------------------------------------------------------------------- */
static long long memo[MAX_N + 1][MAX_N + 1];
static unsigned char computed[MAX_N + 1][MAX_N + 1];

/* Recursive binomial coefficient with memoisation.
 *
 *   C(n,k) = 0                     if k < 0 or n < k
 *   C(n,0) = C(n,n) = 1
 *   otherwise C(n,k) = C(n‑1,k‑1) + C(n‑1,k)
 *
 * The function mirrors the control‑flow of the decompiled `binom`
 * routine, including the early‑return cases.
 */
static long long binom(int n, int k)
{
    /* base cases */
    if (k == 0 || k == n)
        return 1;
    if (n < k || k < 0)
        return 0;

    /* memoisation check */
    if (computed[n][k])
        return memo[n][k];

    /* recursive computation */
    long long a = binom(n - 1, k - 1);
    long long b = binom(n - 1, k);
    long long res = a + b;

    memo[n][k] = res;
    computed[n][k] = 1;
    return res;
}

/* ----------------------------------------------------------------------
 * Helper: parse a decimal integer from a string, ensuring the whole
 * string is consumed and that the value fits into a signed 32‑bit int.
 *
 * Returns 0 on success, non‑zero on failure.
 * ---------------------------------------------------------------------- */
static int parse_int(const char *s, int *out)
{
    char *endptr;
    long val;

    errno = 0;
    val = strtol(s, &endptr, 10);

    /* strtol must have consumed the whole string */
    if (endptr == s || *endptr != '\0')
        return -1;

    /* range check for 32‑bit signed int */
    if (errno == ERANGE || val < INT_MIN || val > INT_MAX)
        return -1;

    *out = (int)val;
    return 0;
}

/* ----------------------------------------------------------------------
 * main – reproduces the state‑machine logic of the original binary.
 * ---------------------------------------------------------------------- */
int main(int argc, char **argv)
{
    int n, k;

    /* ------------------------------------------------------------------
     * Argument count check – the original program required exactly two
     * arguments after the program name.
     * ------------------------------------------------------------------ */
    if (argc < 3) {
        puts(NO_INPUT_MSG);
        return 0;
    }

    /* ------------------------------------------------------------------
     * Parse the two arguments, rejecting any non‑numeric input.
     * ------------------------------------------------------------------ */
    if (parse_int(argv[1], &n) != 0 || parse_int(argv[2], &k) != 0) {
        puts(BAD_INPUT_MSG);
        return 0;
    }

    /* ------------------------------------------------------------------
     * Range check for n (the only range the original binary enforced).
     * ------------------------------------------------------------------ */
    if (n < 0 || n > MAX_N) {
        puts(OUT_OF_RANGE_MSG);
        return 0;
    }

    /* ------------------------------------------------------------------
     * Compute and print the binomial coefficient.
     * ------------------------------------------------------------------ */
    long long result = binom(n, k);
    printf("%lld\n", result);
    return 0;
}
